<?php
$error=null;
if(is_post()){
 try{
  switch(post('action')){
   case 'start': SalesWorkflowService::openHandover(uid(),(int)post('incoming_id'),to_num(post('counted_cash')),post('reason')); flash('ok','Drawer handover started. The incoming Sales Staff must confirm.'); break;
   case 'decide': SalesWorkflowService::decideHandover((int)post('session_id'),uid(),post('decision')==='confirm',post('reason')); flash('ok','Handover response recorded.'); break;
   case 'settle': SalesWorkflowService::settleHandoverDispute((int)post('session_id'),to_num(post('final_count')),post('reason'),uid()); flash('ok','Handover dispute settled.'); break;
   default: throw new UserError('Unknown handover action.');
  }
  redirect('handover');
 }catch(Throwable $e){$error=friendly_error($e);}
}
$session=has_role('Sales','Executive Officer')?SalesService::mySession(uid()):null; $cash=$session?SalesService::sessionCash((int)$session['session_id']):null; $sales=has_role('Sales','Executive Officer')?AdminService::users():[]; $sales=array_values(array_filter($sales,fn($u)=>$u['role']==='Sales'&&$u['status']==='Active'));
$pending=has_role('Sales','Executive Officer')?SalesWorkflowService::pendingHandoverFor(uid()):[];
$disputes=has_role('Executive Officer')?q_all("SELECT ds.*,u.full_name AS outgoing,inm.full_name AS incoming FROM drawer_sessions ds JOIN users u ON u.user_id=ds.sales_staff_id LEFT JOIN users inm ON inm.user_id=ds.handover_to_user_id WHERE ds.handover_confirm='Disputed' ORDER BY ds.session_id DESC"):[];
layout_start('Shift handover','Outgoing Sales Staff counts the drawer; incoming Staff confirms. Differences are logged and disputes can be settled by an Executive Officer.'); echo error_box($error);
?>
<?php if(has_role('Sales','Executive Officer')):?><div class="grid-2"><section class="panel"><h2>Start handover</h2><?php if(!$session):?><div class="empty">You do not have an open drawer.</div><?php else:?><dl class="facts"><dt>Drawer</dt><dd><?=e($session['drawer_no'])?></dd><dt>Expected cash</dt><dd><?=e(money($cash['expected_cash']))?></dd></dl><form method="post" class="stack" style="margin-top:16px"><?=csrf_field()?><input type="hidden" name="action" value="start"><div><label>Incoming Sales Staff</label><select name="incoming_id" required><?=options($sales,'user_id','full_name',null,'Choose colleague')?></select></div><div><label>Counted cash</label><input type="number" min="0" step="0.01" name="counted_cash" value="<?=e($cash['expected_cash'])?>" required></div><div><label>Difference explanation</label><textarea name="reason" rows="2" placeholder="Required if cash is over or short"></textarea></div><button class="btn btn-primary">Start handover</button></form><?php endif;?></section><section class="panel"><h2>Handover waiting for you</h2><?php if(!$pending):?><div class="empty">No incoming handover is waiting.</div><?php else: foreach($pending as $x):?><div class="panel" style="margin:0 0 12px"><strong>Drawer <?=e($x['drawer_no'])?></strong><span class="sub">From <?=e($x['outgoing'])?> · Counted <?=e(money($x['counted_cash']))?></span><form method="post" class="stack" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="action" value="decide"><input type="hidden" name="session_id" value="<?=e($x['session_id'])?>"><textarea name="reason" rows="2" placeholder="Required when disputing"></textarea><div class="btn-row"><button class="btn btn-primary" name="decision" value="confirm">Confirm count</button><button class="btn btn-danger" name="decision" value="dispute">Dispute count</button></div></form></div><?php endforeach; endif;?></section></div><?php endif; ?>
<?php if(has_role('Executive Officer')):?><section class="panel"><h2>Disputed handovers</h2><?php if(!$disputes):?><div class="empty">No disputed handovers.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Drawer</th><th>Outgoing</th><th>Incoming</th><th>Counted</th><th>Settlement</th></tr></thead><tbody><?php foreach($disputes as $x):?><tr><td><?=e($x['drawer_no'])?></td><td><?=e($x['outgoing'])?></td><td><?=e($x['incoming'])?></td><td><?=e(money($x['counted_cash']))?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="settle"><input type="hidden" name="session_id" value="<?=e($x['session_id'])?>"><input type="number" name="final_count" min="0" step="0.01" placeholder="Final cash" required><input type="text" name="reason" placeholder="Settlement reason" required><button class="btn btn-primary btn-sm">Settle</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif; ?>
<?php layout_end();
